    nums = set(re.findall(r'(?<![\d.-])(\d{2,3})(?![\d.])', txt))
    unknown = {n for n in nums if n not in tbl}
    print(f, len(txt), sorted(unknown) if unknown else 'ok')
    used |= (nums & set(tbl))
print('declared but unused:', sorted(set(tbl) - used))

for f in glob.glob('figures/*.md') + glob.glob('draft/*.md'):
